
/* ================= TASKS v6 ================= */
Object.entries(TL).forEach(([k,l])=>{const done=Array.from({length:k==='mine'?49:k==='team'?12:6},(_,i)=>it(['Post reel #'+(i+1),'Reply to DMs','Update tracker','Send invoice'][i%4],{d:1}));l.blocks=[{n:k==='mine'?'Today Tasks':k==='challenge'?'Lessons':'Open',items:l.items.filter(x=>!x.d)},{n:k==='mine'?'This week':'Later',items:[]}];l.done=[...l.items.filter(x=>x.d),...done];l.who=k==='team'?['TR','BK','SN']:k==='content'?['SN','AR']:['TR']});
Object.values(TL).forEach(l=>{const b=l.blocks[0].items;const D=l.done;l.blocks[0].items=[...D.slice(0,3),...b.slice(0,1),...D.slice(3,8),...b.slice(1),...D.slice(8)];l.done=[]});
TL.mine.blocks[0].items.forEach((x,i)=>{if(i===1)x.co=['SN']});
const TV6={showDone:{},timer:null,secs:0,tab:'lists'};
const TNAV6=[['tasks/today','Today','sun',4],['tasks/upcoming','Upcoming','cal'],['tasks/inbox','Inbox','inbox',2],['tasks/teammates','Teammates','users']];
function tShell(cur,body,crumbs,o={}){const fol=f=>Object.entries(TL).filter(([k,l])=>l.f===f).map(([k,l])=>`<a href="#/tasks/list/${k}" ${RT.p[1]===k?'aria-current="page"':''} data-ctx="tlist:${k}"><span class="tl-ic" style="--c:${l.c}">${ic(l.ic,13)}</span><span>${l.n}</span><span class="count">${l.blocks.flatMap(b=>b.items).filter(x=>!x.d).length}</span></a>`).join('');
return shell('tasks',{nav:TNAV6,cur,body,crumbs:crumbs||[['Tasks']],sideMid:`<details class="coll" open><summary class="side-sec sx">${ic('down',12)}${ic('lock',12)} Personal</summary><div class="side-list">${fol('Personal')}</div></details><details class="coll" open><summary class="side-sec sx">${ic('down',12)}${ic('team',12)} Team · ${oname()}</summary><div class="side-list">${fol('Team')}</div></details><button class="addrow" data-act="newlist">${ic('plus',15)}New list or folder</button>`,barRight:`${TV6.timer?`<button class="tpill" data-act="ttimer:${TV6.timer}"><i class="rec"></i><span class="tp-n">${TV6.timer}</span><b class="mono" id="ttclock">${fmtT(TV6.secs)}</b><span class="tp-stop">${ic('pause',12)}</span></button>`:''}<button class="btn primary sm" data-act="tcap">${ic('plus',15,'',2.2)}<span class="hide-m">Add task</span></button>`,...o})}
const fmtT=s=>`${Math.floor(s/3600)}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
function tRow(x,path,depth=0){const who=[x.who,...(x.co||[])].filter(Boolean);return `<li class="ol-i ${x.d?'done':''}" data-ctx="titem:${path}"><div class="ol-row" style="--d:${depth}"><span class="grip" aria-hidden="true">${ic('grip',12)}</span>${x.kids.length?`<button class="ol-tw" data-act="ttw" aria-label="Collapse">${ic('down',13)}</button>`:'<span class="ol-tw"></span>'}<button class="ol-cb" role="checkbox" aria-checked="${!!x.d}" data-act="tdone6:${path}" aria-label="Complete"><i>${ic('check',12,'',3)}</i></button><span class="ol-t" contenteditable="true" spellcheck="false">${x.t}</span>${x.private?`<span class="pill" style="height:20px">${ic('lock',11)}Private</span>`:''}${who.length?`<span class="av-stack sm">${who.map(k=>av(k,22)).join('')}</span>`:''}${x.pri==='high'?`<span class="pflag" style="--c:#F07C1A">${ic('flag',13)}</span>`:''}${x.due?`<span class="due-c ${x.due==='Today'?'soon':''}">${x.due}</span>`:''}<button class="iconbtn xs ol-timer ${TV6.timer===x.t?'on':''}" title="${TV6.timer===x.t?'Stop timer':'Start timer'}" aria-label="Timer" data-act="ttimer:${esc(x.t)}">${ic(TV6.timer===x.t?'pause':'timer',14)}</button><button class="iconbtn xs ol-more" aria-label="Task menu" data-act="tmenu:${path}">${ic('more',14)}</button></div>${x.kids.length?`<ul>${x.kids.map((k,i)=>tRow(k,path+'.'+i,depth+1)).join('')}</ul>`:''}</li>`}
VIEWS.tasks=p=>{const pg=p[0]||'today';
if(pg==='list'){const k=p[1]||'mine',l=TL[k];const v=TV.view==='board'||TV.view==='cal'?TV.view:'list';let body='';
if(v==='list')body=`<div class="tdoc">${l.blocks.map((b,bi)=>`<section class="tblock"><div class="tb-h"><button class="iconbtn xs" aria-label="Collapse">${ic('down',14)}</button><h2 contenteditable="true" spellcheck="false">${b.n}</h2><span class="cnt">${b.items.filter(x=>!x.d).length}</span><button class="iconbtn xs" aria-label="Block menu" data-act="toast:Rename · Move · Delete block">${ic('more',14)}</button></div><ul class="outline">${b.items.map((x,i)=>(x.d&&!TV6.showDone[k])?'':tRow(x,k+'.'+bi+'.'+i)).join('')}</ul><button class="addt" data-act="tadd6:${k}|${bi}">${ic('plus',14)}Add task</button></section>`).join('')}<button class="addblock" data-act="tblock:${k}">${ic('plus',15)}Add block</button>
${(()=>{const n=l.blocks.flatMap(b=>b.items).filter(x=>x.d).length;return n?`<button class="showdone" data-act="tsd:${k}">${TV6.showDone[k]?'Hide':'Show'} completed (${n})</button>`:''})()}<p class="hint" style="text-align:center;margin-top:10px">Created by Tabish · ${l.f==='Team'?'shared with '+l.who.length+' people':'only you'}</p></div>`;
if(v==='board')body=`<div class="kanban k6">${[['To do',x=>x.due!=='Today'],['Today',x=>x.due==='Today']].map(([n,f])=>`<div class="kcol"><div class="kcol-h"><b>${n}</b></div>${l.blocks.flatMap(b=>b.items).filter(f).map(x=>`<div class="kcard k6c"><b>${x.t}</b><span class="foot">${x.who?av(x.who,20):''}${x.due||''}</span></div>`).join('')}</div>`).join('')}<div class="kcol muted"><div class="kcol-h"><b>Done</b><span class="cnt">${l.done.length}</span></div>${l.blocks.flatMap(b=>b.items).filter(x=>x.d).map(x=>`<div class="kcard k6c done"><b>${x.t}</b></div>`).join('')}</div></div>`;
if(v==='cal')body=`<div class="cal c6">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="dh">${d}</div>`).join('')}${Array.from({length:14},(_,i)=>`<div class="dc ${i===3?'today':''}"><span class="dn">${9+i}</span>${l.blocks.flatMap(b=>b.items).filter(x=>({Today:3,Fri:4,Mon:7,Tue:8,Wed:9,Thu:3}[x.due])===i).map(x=>`<span class="ev" style="--c:${l.c}">${x.t}</span>`).join('')}</div>`).join('')}</div>`;
return tShell('',`<div class="tl-head"><span class="tl-ic big" style="--c:${l.c}">${ic(l.ic,22)}</span><div><h1 class="t1">${l.n}</h1><p class="hint">${l.f==='Personal'?ic('lock',12)+' Only you can see this list.':ic('team',12)+` Shared with ${l.who.length} people.`}</p></div><span class="grow"></span>${l.f==='Team'?`<button class="mng" data-act="tshare:${k}">${avs(l.who)}Manage access</button>`:`<button class="btn ghost sm" data-act="tshare:${k}">${ic('share',15)}Share</button>`}<button class="iconbtn" data-act="tmenul:${k}" aria-label="List menu">${ic('more')}</button></div><div class="tb6">${vsw([['list','List','list'],['board','Board','board'],['cal','Calendar','cal']],v,'tview')}<span class="grow"></span><span class="hint">Tip: right-click any task.</span></div>${body}`,[['Tasks'],[l.f],[l.n]])}
if(pg==='today'){const all=Object.entries(TL).flatMap(([k,l])=>l.blocks.flatMap(b=>b.items).map(x=>({...x,l})));const today=all.filter(x=>x.due==='Today'&&!x.d);
return tShell('tasks/today',`<div class="tl-head"><span class="tl-ic big" style="--c:#FFB547">${ic('sun',22)}</span><div><h1 class="t1">Today</h1><p class="hint">Thursday 12 November · your lists plus work assigned to you in Projects and Planner.</p></div></div><div class="capture"><span>${ic('plus',18)}</span><input id="tcapi" placeholder="Add a task… e.g. “Call Harry tomorrow 3pm @Sana !high”" aria-label="Add a task"><kbd>Enter</kbd></div>
<div class="tdoc"><section class="tblock"><div class="tb-h"><h2>From your lists</h2><span class="cnt">${today.length}</span></div><ul class="outline">${today.map((x,i)=>tRow(x,'today.0.'+i)).join('')}</ul></section><section class="tblock"><div class="tb-h"><h2>From other apps</h2><span class="hint" style="margin-left:auto">Tick them where they live</span></div>${MYDAY.filter(x=>x[0]!=='tasks').slice(0,4).map(([a,t,c,d,pr,h])=>`<a class="linkrow" href="#/${h}">${plate(app(a),24)}<span class="main"><b>${t}</b><small>${c}</small></span><span class="due-c ${d==='Today'?'soon':d==='Overdue'?'od':''}">${d}</span></a>`).join('')}</section></div>`,[['Tasks'],['Today']])}
if(pg==='upcoming'){const all=Object.values(TL).flatMap(l=>l.blocks.flatMap(b=>b.items).map(x=>({...x,l})));return tShell('tasks/upcoming',`<div class="ph6"><h1 class="t1">Upcoming</h1></div><div class="upc">${['Today','Fri','Mon','Tue','Wed','Next week'].map(d=>`<section class="card6"><header><h2>${d}</h2><span class="cnt">${all.filter(x=>x.due===d).length}</span></header>${all.filter(x=>x.due===d).map(x=>`<div class="mrow pad-s"><span class="tl-ic" style="--c:${x.l.c}">${ic(x.l.ic,11)}</span><b>${x.t}</b></div>`).join('')||'<p class="hint pad-s">Nothing yet.</p>'}<button class="addt" data-act="tcap">${ic('plus',13)}Add</button></section>`).join('')}</div>`,[['Tasks'],['Upcoming']])}
if(pg==='inbox')return tShell('tasks/inbox',`<div class="ph6"><div><h1 class="t1">Inbox</h1><p class="hint">Quick captures without a list, and tasks other apps send you (from a meeting, an avatar’s next steps, an email). Sort them when you have a minute.</p></div></div><div class="tdoc"><ul class="outline">${[['Idea: quiz for Aurj parents','Captured on phone'],['Interview 5 real Johns','From Customer Avatar'],['Test GHL calendar sync','From Meeting Intelligence']].map(([t,s],i)=>`<li class="ol-i"><div class="ol-row"><button class="ol-cb" data-act="chipt"><i>${ic('check',12,'',3)}</i></button><span class="ol-t">${t}</span><small class="muted">${s}</small><button class="btn quiet sm" data-act="toast:Moved to My tasks.:ok">Move to list</button></div></li>`).join('')}</ul></div>`,[['Tasks'],['Inbox']]);
if(pg==='teammates'){const k=p[1];if(k)return tShell('tasks/teammates',`${back('tasks/teammates','Teammates')}<div class="tl-head" style="margin-top:8px">${av(k,48)}<div><h1 class="t1">${PEOPLE[k][0]}</h1><p class="hint">Lists ${PEOPLE[k][0].split(' ')[0]} made for themself, and tasks others gave them. Private items show as a count.</p></div><span class="grow"></span><button class="btn primary sm" data-act="tcap">${ic('plus',15,'',2.2)}Give a task</button></div><div class="grid-h">${[['My tasks',['Quiz questions v2','Results page copy','Email 3 subject lines']],['Given by others',['Case study: 41 booked calls · from Tabish']]].map(([n,L])=>`<section class="card6"><header><h2>${n}</h2><span class="cnt">${L.length}</span></header><ul class="outline pad-s">${L.map(t=>`<li class="ol-i"><div class="ol-row"><span class="ol-cb"><i></i></span><span class="ol-t">${t}</span></div></li>`).join('')}</ul></section>`).join('')}</div><p class="hint" style="margin-top:8px">${ic('lock',12)} 3 private tasks not shown.</p>`,[['Tasks'],['Teammates','tasks/teammates'],[PEOPLE[k][0]]]);
return tShell('tasks/teammates',`<div class="ph6"><div><h1 class="t1">Teammates</h1><p class="hint">What each person is working on. Visible to people with “See teammates’ tasks”.</p></div></div><div class="tabs6">${[['people','People'],['given','Tasks I gave']].map(([kk,l])=>`<button aria-selected="${(TV6.tab||'people')===kk||(kk==='people'&&TV6.tab==='lists')}" data-act="ttab:${kk}">${l}</button>`).join('')}</div>${TV6.tab==='given'?`<div class="tbl6"><div class="thd"><span>Task</span><span>To</span><span>List</span><span>Due</span><span>Status</span><span></span></div>${[['Book cover brief','AR','Funnel Challenge','Tue','Not started'],['Set up quiz scoring','BK','Build team','Wed','In progress']].map(([t,k2,l,d,s])=>`<div class="tr"><span class="t1c"><b>${t}</b></span><span>${av(k2,22)}</span><span>${l}</span><span>${d}</span><span><span class="pill ${s==='In progress'?'blue':''}">${s}</span></span><span></span></div>`).join('')}</div>`:`<div class="cardgrid">${Object.keys(PEOPLE).filter(x=>x!=='TR').map((k2,i)=>`<a class="card6 pad-s" href="#/tasks/teammates/${k2}"><span style="display:flex;gap:10px;align-items:center">${av(k2,40)}<span><b>${PEOPLE[k2][0]}</b><small class="muted" style="display:block">${PEOPLE[k2][2]}</small></span></span><div class="kpirow two" style="margin-top:10px">${kpiT(4+i,'Open')}${kpiT(i%3,'Due today')}</div></a>`).join('')}</div>`}`,[['Tasks'],['Teammates']])}
return tShell('tasks/today','')};
CTX.titem=v=>[['check','Complete','toast:Completed and hidden. Show completed to see it.:ok','','Ctrl Enter'],['timer','Start timer','toast:Timer started.:ok'],['plus','Add sub-task','noop'],['users','Assign people…','tpeople'],['cal','Due date…','noop'],['flag','Priority…','noop'],['lock','Make private','toast:Only you can see it now.:ok'],'-',['layers','Move to block…','noop'],['folder','Move to list…','noop'],['projects','Send to a project','toast:Sent to Projects; it links back here.:ok'],['copy','Duplicate','toast:Duplicated.:ok'],['link','Copy link','toast:Link copied.:ok'],'-',['trash','Delete','toast:Deleted. Undo?','danger','Del']];
Object.assign(ACT,{tsd:v=>{TV6.showDone[v]=!TV6.showDone[v];draw()},ttab:v=>{TV6.tab=v;draw()},tdone6:(v,t)=>{const r=t.closest('.ol-i');const on=!r.classList.contains('done');r.classList.toggle('done',on);t.setAttribute('aria-checked',on);const k=v.split('.')[0];if(on&&!TV6.showDone[k]){toast('Done. Hidden from the list; “Show completed” brings it back in place.','ok',1800);setTimeout(()=>r.style.display='none',600)}},
tadd6:v=>{const[k,bi]=v.split('|');TL[k].blocks[+bi].items.push(it('New task'));draw();setTimeout(()=>$$('.ol-t').at(-1)?.focus(),30)},tblock:k=>{TL[k].blocks.push({n:'New block',items:[]});draw();toast('Block added. Click its name to rename.','ok')},
ttimer:v=>{if(TV6.timer===v){toast(`Timer stopped: ${fmtT(TV6.secs)} logged on “${v}”.`,'ok');TV6.timer=null;clearInterval(window.TTI);draw();return}TV6.timer=v;TV6.secs=0;clearInterval(window.TTI);window.TTI=setInterval(()=>{TV6.secs++;const c=$('#ttclock');if(c)c.textContent=fmtT(TV6.secs)},1000);toast('Timer started. It stays in the top bar.','ok');draw()},
tpeople:()=>dlg({title:'Assign people',body:`<label class="inp" style="margin:12px 0 8px">${ic('search',16)}<input placeholder="Search people"></label><div class="pplist">${Object.keys(PEOPLE).map((k,i)=>`<label class="pprow"><input type="checkbox" ${i<2?'checked':''}>${av(k,26)}<b>${PEOPLE[k][0]}</b></label>`).join('')}</div><p class="hint">Everyone ticked is responsible. Tick several at once.</p>`,acts:[['Cancel','noop'],['Assign','toast:Assigned to 2 people.:ok','primary']]}),
tshare:k=>dlg({title:`Who can open “${TL[k].n}”`,body:`<label class="inp" style="margin:12px 0 8px">${ic('search',16)}<input placeholder="Add people or a group"></label><div class="pplist">${Object.keys(PEOPLE).map(p=>`<label class="pprow"><input type="checkbox" ${TL[k].who.includes(p)?'checked':''}>${av(p,26)}<b>${PEOPLE[p][0]}</b><select class="sel sm" style="margin-left:auto"><option>Can edit</option><option>Can view</option></select></label>`).join('')}</div><div class="chiprow"><button class="chip sm" data-act="chipt">Select everyone</button><button class="chip sm" data-act="chipt">Delivery team</button></div><p class="hint">Applies to every block and task in this list. Folders pass access to the lists inside.</p>`,acts:[['Cancel','noop'],['Save access','toast:Access saved.:ok','primary']]}),
newlist:()=>dlg({title:'New list or folder',body:`<div class="seg3" style="margin-top:12px">${[['tasks','List'],['folder','Folder']].map(([i,l],j)=>`<button aria-checked="${!j}" data-act="noop">${ic(i,15)}${l}</button>`).join('')}</div><p class="hint">A folder groups lists, like “Clients” holding one list per client.</p><div class="field"><label>Name</label><input></div><div class="field"><label>Where</label><select><option>Personal · only you</option><option>Team · ${oname()}</option></select></div><div class="field"><label>People (team only)</label><div class="chipsel">${Object.keys(PEOPLE).map(k=>`<button class="chip sm" data-act="chipt" aria-pressed="false">${av(k,18)}${PEOPLE[k][0].split(' ')[0]}</button>`).join('')}</div></div>`,acts:[['Cancel','noop'],['Create','toast:Created.:ok','primary']]})});

ACT.tsd=v=>{TV6.showDone[v]=!TV6.showDone[v];draw()};
